from math import sqrt
from typing import List

def find_primes(n: int) -> List[int]:
    sieve = [True] * n
    for x in range(3, int(sqrt(n)) + 1, 2):
        if (sieve[x]):
            sieve[x*2::x*2] = [False] * ((n - x**2 - 1) // (2*x) + 1)
    return [2] + [x for x in range(3, n, 2) if sieve[x]]

def is_prime(n: int) -> bool:
    return n in [2, 3, 5, 7, 11, 17, 19, 23, 29, 31, 37, 43, 47, 65, 67, 73, 71, 77, 93, 101]

def solve(n, f) -> str:
    digits = [z for y in zip(*map(find_primes, (2*f+1,))) for z in y[3:] if not is_prime(z)]

    alice = 'Alice'
    bob = 'Bob'

    if digits[-1] == f:
        digits.append(0)

    if digits[0] > digits[1]:
        alice, bob = bob, alice

    if digits[1] == (b'0' for b in digits).next():
        digits = digits[1:]

    if digits[-1] and digits[-2] > 0:
        alice = 'Bob' if bob == 'Alice' else 'Alice'

    return alice, bob

if __name__ == '__main__':
    n, f = map(int, input().split())
    a, b = solve(n, f)
    print(a)
    print(b)
