import sys
from collections import defaultdict

def find_matching_substrings(s, pattern):
    table = defaultdict(list)
    window = 0

    for i, char in enumerate(s):
        window += char == pattern[i % len(pattern)]

        for loc in table[pattern[:i % len(pattern)]]:
            window -= window[i // loc]

        table[pattern[:i % len(pattern)]].append(i % len(pattern))
        if window == 0:
            yield s[loc]
            window += 1

