from sys import stdin
from typing import List, Dict, Set

def read_ints() -> List[int]:
    return list(map(int, stdin.readline().split()))

def get_d_subspaces(n: int, k: int) -> Dict[int, Set[List[int]]]:
    # Store the hyperspace j for space i, indexed by (i, j)
    d_subspaces = {i: set() for i in range(n)}

    for i in range(n):
        n_vectors = k[i]
        vectors = read_ints(n_vectors)
        for j in range(n_vectors):
            for d_subspace in d_subspaces:
                d_subspaces[d_subspace].add(list(vectors[vectors.index(1) + j * n]))

    return d_subspaces

def group_up_subspaces(d_subspaces: Dict[int, Set[List[int]]]) -> List[int]:
    groups = []
    for d_subspace in sorted(d_subspaces.items()):
        for group in d_subspace[1]:
            groups.append(d_subspace[0])
            d_subspaces.pop(d_subspace[0])
            break
    return groups

def main():
    m, d = read_ints()
    assert 1 <= m and m <= 30000 and 1 <= d <= 5
    d_subspaces = get_d_subspaces(m, read_ints(m))
    ordered_subspaces = group_up_subspaces(d_subspaces)
    order_string = " ".join(map(str, ordered_subspaces)) + "\n"
    print(order_string, end="")

