def lcm(a, b):
    return a * b // gcd(a, b)

def expand(v):
    return set((x, v.count(x)) for x in set(v))

def expand_to_vector(vectors):
    expanded = reduce(lcm, (map(lambda x: tuple(sorted(expand(v))),
                               vectors)), 1)
    return (1, tuple(sorted({'0' : expanded})))[len(set(vectors))]

def subgroup(u, g_vectors):
    cyclic = subgroup_helper(u, g_vectors, set())
    _, groups = extend(cyclic)
    groups = list(compress(groups, groups))
    groups.sort()
    return groups

def subgroup_helper(sub, group_vectors, used):
    if not group_vectors:
        return sub, group_vectors

    if sub, group_vectors in used:
        return tuple(subgroup_helper(sub, group_vectors, used))

    candidate = next(zip([len(e) for e in group_vectors], group_vectors), (0,
                                                                          []))[1]  
    used.add((sub, group_vectors))
    sub, g_vector = subgroup_helper(sub, group_vectors, used)
    subgroup = expand_to_vector([sub]) | expand_to_vector(g_vector)
    return sub, g_vector

def extend(subgroup):
    for group in subgroup:
        for index, vec in enumerate(g_vectors, start=1):
            sample = [c for c in obtag if group[-c] == index] + [0]
            yield group + tuple(sample)

def group_ray(vectors):
    g_vectors = {}
    for v in vectors:
        zipped_v = [expand_to_vector(vectors)] * (len(g_vectors) + 1)
        for i in range(len(zipped_v), len(g_vectors) + 1):
            zipped_v = map(None, *grid, *zipped_v)
            zipped_v = list(zipped_v)
            group = expand_to_vector(g_vectors)
            g_vectors += {i: group}
        # max(tree_path(values))
        for g in expand_to_vector(vectors):
            g_vectors[i] = g

    return subgroup(vectors.center, group_vectors) + [0]

