def is_winner(turns, operations, product):
    # Check if Alice wins
    if turns < 3:
        return "Alice"
    elif operations == [False, False, False, False, False]:
        return "Alice"

    # Check if Bob wins
    if turns >= 6 and turns <= 9:
        for i in range(turns - 5):
            turns -= operations[i]
            if turns < 3:
                return "Bob"
        for i in range(5, turns - 2):
            turns -= operations[i]
            if turns < 3:
                return "Bob"
        return "Bob"
    else:
        for i in range(6, turns - 4):
            turns -= operations[i]
            if turns < 3:
                return "Bob"
        for i in range(5, turns - 3):
            turns -= operations[i]
            if turns < 3:
                return "Bob"
        return "Alice"

def determine_winner(n, f, b_0, w_0, r_0):
    operations = [False] * (n-1) + [True] * 2
    if f:
        operations[b_0] = True
        operations[w_0] = True

    wins_alexs, wins_bob = 0, 0
    for _ in range(1, n+1):
        winners = is_winner(_, operations, f)
        if winners == "Alice":
            wins_alexs += 1
        elif winners == "Bob":
            wins_bob += 1

    if wins_alexs > wins_bob:
        return "Alice"
    else:
        return "Bob"

