def merge_intervals(intervals):
    merged = []
    for interval in sorted(intervals):
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

def vasya_experience(intervals, petya_intervals, max_diff):
    merged_intervals = merge_intervals(intervals + petya_intervals)
    max_experience = 0
    for i in range(1, len(merged_intervals)):
        experience = merged_intervals[i][1] - merged_intervals[i-1][0]
        if experience <= max_diff:
            max_experience = max(max_experience, merged_intervals[i-1][1] + merged_intervals[i-1][1])
        elif experience > max_diff:
            max_experience = max(max_experience, merged_intervals[i-1][1] + (merged_intervals[i-1][1] // 2))
    return max_experience

