        best_strings = []
        for i in range(1, len(strings)//2 + 1):
            if len(strings) % 2 == 0:
                pairs = [(strings[i*2], strings[i*2 + 1])]
            else:
                pairs = [(strings[(i-1)*2], strings[(i-1)*2 + 1])]
            for j in range(i//2):
                pairs.append((strings[-j*i], strings[-j]))
            pairs.sort(key=lambda x: len(x))
            current_length = 0
            for s, e in pairs:
                current_length += e
                if current_length > max_length:
                    max_length = current_length
                    best_strings = [s, s + e]
        return best_strings, max_length

    # Process the input string
