class StreamProcessor:
    def __init__(self, s):
        self.s = s
        self.prefix_sum = collections.defaultdict(int)
        self.char_count = {}
        for i, char in enumerate(s):
            self.prefix_sum[i] = self.prefix_sum[i-1] + 1 if i > 0 else 1
            self.char_count[char] = self.char_count[char] + 1 if char not in self.char_count else 1

    def count_cyclic_isomorphic_substrings(self, query):
        query_count = {}
        ans = 0
        for char in query:
            query_count[char] = query_count[char] + 1 if char in query_count else 1
        for i, char in enumerate(self.s):
            if len(char) == len(query) and self.char_count[char] == len(char) and self.prefix_sum[i] == len(query):
                ans += 1
            if i >= len(query) - 1:
                if len(self.s[i-len(query)+1:i+1]) == len(query) and self.char_count[self.s[i-len(query)+1:i+1]] > 0:
                    ans += 1
                if char in self.char_count and self.char_count[char] > 0:
                    ans -= 1
                    if i + 1 >= len(query) - len(char) or i + 1 >= len(query):
                        query_count[char] -= 1
                    else:
                        for char2 in query:
                            if self.get_rotation_id(char2, self.s[i+1:i+1+len(char2)]) == 0:
                                query_count[char2] -= 1
            if i+1 < len(query):
                if len(self.s[0:i+1]) == len(query) and self.char_count[self.s[0:i+1]] > 0:
                    ans += 1
                if char in self.char_count and self.char_count[char] > 0:
                    ans += 1
                    query_count[char] += 1
        return ans / len(self.s) * len(self.s)

def process(train_s, n, queries):
    processor = StreamProcessor(train_s)
    return [processor.count_cyclic_isomorphic_substrings(query) for query in queries]

if __name__ == "__main__":
    # Read input
    s = input().strip()
    n = int(input().strip())
    queries = [input().strip() for _ in range(n)]

    # Process queries
    results = process(s, n, queries)

    # Output results
