from typing import List
import heapq

def find_min_m(n: int, k: int, numbers: List[int]) -> int:
    min_heap = []
    for number in numbers:
        heapq.heappush(min_heap, number)
        if len(min_heap) > n - k:
            heapq.heappop(min_heap)
    dp = [min_heap[0], 0]
    dp[-1] = min_heap[0]

    for number in numbers:
        if number < dp[0]:
            dp = dp[:1] + [dp[-1], number]
        else:
            for i in range(len(dp) - 1, -1, -1):
                if dp[i] + min_heap[0] > number:
                    break
                dp[i+1] = max(dp[i], number - min_heap[0])
        if number < dp[-1]:
            dp = dp + [number]

    return dp[0]

