from math import sqrt, isqrt
from itertools import product

def isqrtinv(n):
    return isqrt(n)**2 == n

def is_perm_square(i, j):
    return i**2 == (i - j)**2 + j

def count_right_permutations(n, a):
    count = 0
    for p in product(range(n), repeat=n):
        for i in range(n):
            if i < n-1 and is_perm_square(p[i], p[i+1]):
                break
        else:
            valid = True
            for i in range(n):
                for j in range(i+1, n):
                    if not is_perm_square(a[i], a[j]):
                        valid = False
                        break
                if not valid:
                    break
            if valid: count += 1
    return count % (10**9 + 7)

