def find_group_numbers(subspaces: List[List[Tuple[int, int]]]) -> List[int]:
    groups = [0] * len(subspaces)

    def generate_vector(subspace: List[Tuple[int, int]]) -> List[int]:
        vector: List[int] = []
        for i in range(len(subspace)):
            for j in range(len(subspace)):
                vector.append(subspace[i][j] * i + subspace[j][0] * j)
        return vector

    group = 1
    subspace_set = set()

    for i in range(len(subspaces)):
        vector = generate_vector(subspaces[i])

        if i == 0:
            continue

        for j in range(i):
            if set(vector) == set(subspaces[j][0]):
                subspaces[j] = subspace_set
                break

        if not vector in subspace_set:
            subspaces[i] = subgroup = subspaces[i][0]

            for j in range(i + 1, len(subspaces)):
                if set(vector) == set(subspaces[j][0]):
                    group += 1
                    vector_vec = generate_vector(subspaces[j])

                    for k in range(j + 1, len(subspaces)):
                        if set(vector_vec) == set(subspaces[k][0]):
                            group += 1
                            continue

                        if set(vector) == set(generate_vector(subspaces[k])):
                            subgroup = max(subgroup, subspaces[k])
                            group += 1
                            vector_vec = generate_vector(subspaces[k])

            subspace_set.add((vector, group))

            for l in range(len(subspaces)):
                if set(vector) == set(subspaces[l][0]):
                    groups[l] = group
                    break

    return groups

