from math import gcd
from typing import List, Tuple

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def reduce_fraction(frac: Tuple[int, int]) -> Tuple[int, int]:
    denominator = lcm(*frac)
    return tuple(x*y // denominator for x, y in zip(*frac))

def solve_for_mass(dim: int, ships: List[List[Tuple[int, int]]]) -> List[int]:
    if dim == 1:
        return [i + 1 for i in range(len(ships))]

    masses = len(ships)
    total_masses = [reduce_fraction(ship) for ship in ships]

    result = [next_id] * masses
    for total_id, total_mass in enumerate(total_masses, start=1):
        for m_id, mass in enumerate(total_mass, start=1):
            if mass[0] == total_id:
                result[m_id-1] = result[result.index(total_id) - 1] = m_id
            elif mass[1] == total_id:
                result[m_id-1] = result[result.index(total_id) - 1] = total_id

    return result

