import sys

# Function to calculate factorial mod
def factorial_mod(m, p, n):
    # Base case
    if n == 0:
        return m
    # If n > m, use divmod for m/n and y//2 = y/2
    if n > m:
        return m / p - factorial_mod(m / p, p, n - m / p) * (n % m)
    # Divmod for n/2, add y%m and x*(m/2), and continueif n > m
    k, r = divmod(n, 2)
    return m - (factorial_mod(m - p, p, k * m % p) * (n % m) + (m / p - factorial_mod(m / p, p, k * m / p) * (n % m) // 2) * r)

# Function to calculate binomial coefficient mod
def binomial_coefficient_mod(m, n, p):
    return factorial_mod(n + 1, p, max(0, m - n)) / objective_mod(m + 1, p, m)

# Function to calculate objective mod
def objective_mod(m, p, a):
    # Counter for each a
    count = {i: 0 for i in range(p)}
    # Function to check if n > m or n and a are not equal
    def modified(m, n, a):
        if n and a in count:
            return m // count[a] - modified(m // 2, n // 2, a) * (m % 2)
        elif n:
            return m // (m // 2) - modified(m // 2, n // 2, a) * (n % 2)
        else:
            return m - (1 - modified(m, n, a) * 2)
    return modified(m, n, a)

