                    left = parse_planet1(planets[i])
                remaining.discard(left)
                remaining.add(i)
            if planets[i][0] > planet[0]:
                right = parse_planet2(planets[i])
                while right not in remaining:
                    right = parse_planet1(planets[i])
                remaining.discard(right)
                remaining.add(i)

    # Return the number of remaining planets
    return len(remaining)

def parse_planet1(planet: List[int]) -> int:
    return planet[1] - 0.5

def parse_planet2(planet: List[int]) -> int:
    return planet[1] + 0.5

# Example usage
n = int(input().strip())
planets = []
for _ in range(n):
    planet = list(map(int, input().strip().split()))
    planets.append(planet)

result = count_universes(planets)
print(result)
