# Function to calculate factorial of a number modulo p
def factorial_mod(p, n):
    if n == 0:
        return 1
    x = factorial_mod(p, n // 2) * factorial_mod(p, n // 2)
    x = x % p
    if n % 2 == 0:
        return x
    return x * n % p

# Function to calculate number of groups such that ai1 & ai2 & ... & aik = 0
def count_groups(n, a):
    p = 1000000007
    ans = 1
    coprimes = [1]
    for i in range(n):
        coprime = 1
        for j in range(i + 1):
            if gcd(i + 1 - j, i) == 1:
                coprime = coprime * (i + 2 - j) % p
            else:
                coprime = coprime * j % p
        coprimes += [coprime]
    for i in range(n):
        if i != 0:
            ans = (ans * coprimes[i] % p - 1) % p
    return ans

print(count_groups(n, a))
