from math import isqrt
from itertools import permutations

def is_square(n):
    return isqrt(n)**2 == n

def count_right_permutations(n, a):
    count = 0
    factorial_mod = 1

    for perm in permutations(a):
        for i in range(n - 1):
            if is_square(perm[i] * perm[i + 1]):
                break
        else:
            count += 1
            factorial_mod = (factorial_mod * (n - i - 2) % 1000000007) % 1000000007

    return (count * factorial_mod) % 1000000007

n = int(input())
a = list(map(int, input().split()))

